	(8,'Diskusi tentang korupsi [COLD thread]','<p><b><font color=\"#ce0000\">Hello</font></b></p><p><img src=\"data:image/jpeg;base64,',18,'','2021-12-25 17:49:23','2022-01-23 22:35:49'),
