INSERT INTO `tbl_survey_question` (`id_survey_question`, `code`, `question`, `variabel`, `created_date`)
VALUES
	(10,'q266','Apakah anggota DPRD menjalankan fungsinya  Legislasi yang berkaitan dengan pembentukan peraturan daerah, Anggaran, Kewenangan dalam hal anggaran daerah(APBD) dan  melalukan pengawasan, Kewenangan mengontrol pelaksanaan perda dan peraturan lainnya serta kebijakan pemerintah daerah?','2','2022-03-13 17:14:32'),
	(11,'q178','Apakah anggota DPRD sering memberikan informasi kegiatan DPRD di media sosial','2','2022-03-13 17:15:50'),
	(12,'q444','Apakah anggota DPRD sering menerima laporan, jejak pendapat, pengaduan dll di media sosial','2','2022-03-13 17:16:15'),
	(13,'q331','Apakah anggota DPRD menerima  laporan dan pengaduan tersebut untuk kemudian ditindak lanjuti','2','2022-03-13 17:16:35'),
	(14,'q913','Apa hubungan antara anggota DPRD dengan DISKOMINFO dalam hal pengaduan atau laporan di sosial media.','2','2022-03-13 17:17:03'),
	(15,'q955','Kompetensi anggota DPRD sangat menentukan perubahan posisi atau tugas, wewenang dan tanggung jawab di dewan komisioner.','2','2022-03-13 17:17:28'),
	(16,'q950','Anggota DPRD  sering melakukan survei  lapangan dan memberikan laporan survey dan meresponnya.','2','2022-03-13 17:17:50'),
	(17,'q619','Apakah anggota DPRD sering melihat forum di media sosial dan menanggapinya.','2','2022-03-13 17:18:12'),
	(18,'q111','Dalam hal memutuskan kebijakan apakah anggota DPRD melakukan rapat terlebih dahulu.','2','2022-03-13 17:18:33'),
	(19,'q912','Anggota DPRD akan memberikan rekomendasi pilihan terhadap partai yang akuntabilitas dan elektabilitasnya  baik.','2','2022-03-13 17:18:55'),
	(20,'q218','Apakah partai politik sering menjawab pertanyaan politik dari para pedukungnya di media sosial.','1','2022-03-13 17:19:20'),
	(21,'q197','Apakah partai politik menjunjung solidaritas simpatisannya','1','2022-03-13 17:19:40'),
	(22,'q301','Apakah partai politik selalu berpihak kepada lembaga yang menguntungkan partainya','1','2022-03-13 17:19:56'),
	(23,'q815','Dalam hal Integritas, apakah partai sering melakukan sering konsolidasi dengan para pendukungnya untuk penyamaan persepsi dan pendapat.','1','2022-03-13 17:20:21'),
	(24,'q96','Apakah partai sering melakukan perubahan demografis pemilihnya.','1','2022-03-13 17:20:37'),
	(25,'q323','Apakah cara partai menyikapi para pendukung partai yang sering menghujat  elektabilitas  partai sudah efektif.','1','2022-03-13 17:20:54'),
	(27,'q645','Apakah partai dengan leluasa mengkritisi kebijakan pemerintah yang dinilai merugikan rakyat.','1','2022-03-13 17:21:27'),
	(28,'q586','Apakah partai memberikan solusi apabila terjadi konflik internal yang akan menimbulkan gerakan memecah belah partai di media sosial.','1','2022-03-13 17:22:10'),
	(29,'q363','Apakah partai secera terbuka(inklusif) mempertahakan ekslusivitasnya dalam hal pemkaderannya.','1','2022-03-13 17:22:28'),
	(31,'q955','Apakah cara parpol menangani masalah rakyat sudah efektif ','1','2022-03-15 21:25:22');
